* {{ margin: 0; padding: 0; box-sizing: border-box; }}
body {{
    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
    background: {PALETTE["neutral1"]};
    color: {PALETTE["text"]};
    line-height: 1.6;
}}
.container {{ max-width: 1200px; margin: 0 auto; padding: 20px; }}

/* Hero Header */
.hero {{
    background: linear-gradient(135deg, {PALETTE["primary"]} 0%, #154360 100%);
    color: white;
    padding: 50px 40px;
    border-radius: 12px;
    margin-bottom: 30px;
    text-align: center;
}}
.hero h1 {{ font-size: 2.2em; font-weight: 700; margin-bottom: 8px; }}
.hero .subtitle {{ font-size: 1.1em; opacity: 0.85; }}
.hero .date {{ font-size: 0.9em; opacity: 0.7; margin-top: 6px; }}

/* KPI Cards */
.kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: 20px;
    margin-bottom: 30px;
}}
.kpi-card {{
    background: white;
    border-radius: 10px;
    padding: 24px;
    text-align: center;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
    border-top: 4px solid {PALETTE["secondary"]};
}}
.kpi-card.primary {{ border-top-color: {PALETTE["primary"]}; }}
.kpi-card.accent1 {{ border-top-color: {PALETTE["accent1"]}; }}
.kpi-card.accent2 {{ border-top-color: {PALETTE["accent2"]}; }}
.kpi-card.accent4 {{ border-top-color: {PALETTE["accent4"]}; }}
.kpi-card .label {{ font-size: 0.8em; text-transform: uppercase; color: #7f8c8d; letter-spacing: 0.5px; margin-bottom: 8px; }}
.kpi-card .value {{ font-size: 2em; font-weight: 700; color: {PALETTE["text"]}; }}
.kpi-card .sub {{ font-size: 0.85em; color: #95a5a6; margin-top: 4px; }}
.kpi-card .delta {{ font-size: 0.9em; font-weight: 600; margin-top: 4px; }}
.kpi-card .delta.positive {{ color: {PALETTE["accent2"]}; }}
.kpi-card .delta.negative {{ color: {PALETTE["accent3"]}; }}

/* Section Styling */
.section {{
    background: white;
    border-radius: 10px;
    padding: 32px;
    margin-bottom: 24px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}}
.section h2 {{
    font-size: 1.4em;
    color: {PALETTE["primary"]};
    border-bottom: 2px solid {PALETTE["neutral2"]};
    padding-bottom: 12px;
    margin-bottom: 24px;
}}
.section h3 {{ font-size: 1.1em; color: {PALETTE["text"]}; margin: 24px 0 12px; }}

/* Charts */
.chart-container {{
    position: relative;
    width: 100%;
    margin: 20px 0;
}}
.chart-row {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin: 20px 0;
}}
@media (max-width: 768px) {{
    .chart-row {{ grid-template-columns: 1fr; }}
}}

/* Tables */
.data-table {{
    width: 100%;
    border-collapse: collapse;
    margin: 16px 0;
    font-size: 0.9em;
}}
.data-table th {{
    background: {PALETTE["primary"]};
    color: white;
    padding: 10px 14px;
    text-align: left;
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.78em;
    letter-spacing: 0.5px;
}}
.data-table td {{
    padding: 10px 14px;
    border-bottom: 1px solid {PALETTE["neutral2"]};
}}
.data-table tr:nth-child(even) {{ background: #f8f9fa; }}
.data-table tr:hover {{ background: #e8f0fe; }}
.data-table .num {{ text-align: right; font-variant-numeric: tabular-nums; }}

/* Insight box */
.insight-box {{
    background: linear-gradient(135deg, #eaf2f8, #d4e6f1);
    border-left: 4px solid {PALETTE["secondary"]};
    padding: 16px 20px;
    margin: 20px 0;
    border-radius: 0 8px 8px 0;
    font-size: 0.92em;
}}

/* Highlight callout */
.highlight {{ font-weight: 700; color: {PALETTE["primary"]}; }}
.highlight-green {{ font-weight: 700; color: {PALETTE["accent2"]}; }}
.highlight-red {{ font-weight: 700; color: {PALETTE["accent3"]}; }}

/* Footer */
.footer {{
    text-align: center;
    padding: 20px;
    color: #95a5a6;
    font-size: 0.82em;
}}

/* Two-col layout for tables */
.two-col {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
}}
@media (max-width: 768px) {{
    .two-col {{ grid-template-columns: 1fr; }}
}}
</style>
</head>
<body>
