#!/usr/bin/env python3
"""Generate Chocolate Retail Sales Performance Report (2023-2024)."""

import pandas as pd
import json
from datetime import datetime
import numpy as np

# ── Color palette (professional, management-friendly) ──
PALETTE = {
    "primary":   "#1B4F72",  # deep navy
    "secondary": "#2E86C1",  # medium blue
    "accent1":   "#E67E22",  # warm amber
    "accent2":   "#27AE60",  # green
    "accent3":   "#C0392B",  # red
    "accent4":   "#8E44AD",  # purple
    "neutral1":  "#F4F6F6",  # light grey bg
    "neutral2":  "#E5E8E8",  # medium grey
    "neutral3":  "#BDC3C7",  # darker grey
    "text":      "#2C3E50",   # dark text
    "white":     "#FFFFFF",
}

CHART_COLORS = [PALETTE["primary"], PALETTE["accent1"], PALETTE["secondary"],
                PALETTE["accent2"], PALETTE["accent4"], PALETTE["accent3"],
                "#3498DB", "#F1C40F", "#1ABC9C", "#E74C3C"]

# ── Load data ──
print("Loading data...")
df = pd.read_csv("/app/benchmark/data.csv")
df["order_date"] = pd.to_datetime(df["order_date"])
df["year"] = df["order_date"].dt.year
df["month"] = df["order_date"].dt.month
df["quarter"] = df["order_date"].dt.quarter
df["year_month"] = df["order_date"].dt.to_period("M")
df["year_quarter"] = df["order_date"].dt.to_period("Q")
df["profit_margin"] = df["profit"] / df["revenue"]
df["has_discount"] = df["discount"] > 0

print(f"Loaded {len(df):,} transactions from {df['order_date'].min().date()} to {df['order_date'].max().date()}")

# ── KPI calculations ──
total_revenue = df["revenue"].sum()
total_profit = df["profit"].sum()
total_orders = len(df)
avg_profit_margin = (df["profit"].sum() / df["revenue"].sum()) * 100
avg_order_value = df["revenue"].mean()
discount_utilization = (df["has_discount"].sum() / total_orders) * 100

print(f"Total Revenue: ${total_revenue:,.2f}")
print(f"Total Profit: ${total_profit:,.2f}")
print(f"Avg Profit Margin: {avg_profit_margin:.2f}%")
print(f"Avg Order Value: ${avg_order_value:.2f}")
print(f"Discount Utilization: {discount_utilization:.2f}%")

# ── 1. Executive Summary ──
# Year-over-year comparisons
yoy = df.groupby("year").agg(
    revenue=("revenue", "sum"),
    profit=("profit", "sum"),
    orders=("order_id", "count"),
    avg_margin=("profit_margin", "mean"),
    aov=("revenue", "mean"),
).reset_index()

revenue_2023 = yoy[yoy["year"] == 2023]["revenue"].values[0]
revenue_2024 = yoy[yoy["year"] == 2024]["revenue"].values[0]
revenue_growth = ((revenue_2024 - revenue_2023) / revenue_2023) * 100

profit_2023 = yoy[yoy["year"] == 2023]["profit"].values[0]
profit_2024 = yoy[yoy["year"] == 2024]["profit"].values[0]
profit_growth = ((profit_2024 - profit_2023) / profit_2023) * 100

orders_2023 = int(yoy[yoy["year"] == 2023]["orders"].values[0])
orders_2024 = int(yoy[yoy["year"] == 2024]["orders"].values[0])
orders_growth = ((orders_2024 - orders_2023) / orders_2023) * 100

# ── 2. Sales Trends Over Time ──
monthly = df.groupby("year_month").agg(
    revenue=("revenue", "sum"),
    profit=("profit", "sum"),
    orders=("order_id", "count"),
).reset_index()
monthly["year_month_str"] = monthly["year_month"].astype(str)
# split into 2023 and 2024 for charting
monthly_2023 = monthly[monthly["year_month_str"].str.startswith("2023")]
monthly_2024 = monthly[monthly["year_month_str"].str.startswith("2024")]

quarterly = df.groupby("year_quarter").agg(
    revenue=("revenue", "sum"),
    profit=("profit", "sum"),
    orders=("order_id", "count"),
).reset_index()
quarterly["year_quarter_str"] = quarterly["year_quarter"].astype(str)

# Monthly data as JSON for charts
monthly_data = monthly.to_dict(orient="records")
quarterly_data = quarterly.to_dict(orient="records")

# ── 3. Product Performance ──
# Top products by revenue
product_perf = df.groupby("product_id").agg(
    revenue=("revenue", "sum"),
    profit=("profit", "sum"),
    orders=("order_id", "count"),
    avg_unit_price=("unit_price", "mean"),
    avg_discount=("discount", "mean"),
    avg_margin=("profit_margin", "mean"),
).reset_index()
product_perf["profit_margin_pct"] = (product_perf["profit"] / product_perf["revenue"]) * 100
top10_revenue = product_perf.nlargest(10, "revenue")
top10_profit = product_perf.nlargest(10, "profit")

# Bottom 5 products by revenue
bottom5 = product_perf.nsmallest(5, "revenue")

# Revenue concentration (top 20%)
product_perf_sorted = product_perf.sort_values("revenue", ascending=False)
product_perf_sorted["cum_pct"] = product_perf_sorted["revenue"].cumsum() / product_perf_sorted["revenue"].sum() * 100
n_top20 = max(1, int(len(product_perf_sorted) * 0.2))
top20_revenue_pct = product_perf_sorted.iloc[:n_top20]["revenue"].sum() / product_perf_sorted["revenue"].sum() * 100

# ── 4. Store Performance ──
store_perf = df.groupby("store_id").agg(
    revenue=("revenue", "sum"),
    profit=("profit", "sum"),
    orders=("order_id", "count"),
    avg_margin=("profit_margin", "mean"),
    avg_discount=("discount", "mean"),
).reset_index()
store_perf["profit_margin_pct"] = (store_perf["profit"] / store_perf["revenue"]) * 100
top10_stores_revenue = store_perf.nlargest(10, "revenue")
top10_stores_profit = store_perf.nlargest(10, "profit")
bottom5_stores = store_perf.nsmallest(5, "revenue")

# ── 5. Discount Impact ──
# Categorize discount levels
def discount_bucket(d):
    if d == 0:
        return "0%"
    elif d <= 0.10:
        return "1-10%"
    elif d <= 0.20:
        return "11-20%"
    elif d <= 0.30:
        return "21-30%"
    else:
        return "30%+"

df["discount_bucket"] = df["discount"].apply(discount_bucket)
bucket_order = ["0%", "1-10%", "11-20%", "21-30%", "30%+"]

discount_analysis = df.groupby("discount_bucket").agg(
    transactions=("order_id", "count"),
    total_revenue=("revenue", "sum"),
    total_profit=("profit", "sum"),
    avg_order_value=("revenue", "mean"),
    avg_quantity=("quantity", "mean"),
    avg_profit_margin=("profit_margin", "mean"),
).reset_index()
discount_analysis["pct_margin"] = (discount_analysis["total_profit"] / discount_analysis["total_revenue"]) * 100
discount_analysis["pct_transactions"] = (discount_analysis["transactions"] / total_orders) * 100
discount_analysis = discount_analysis.set_index("discount_bucket").reindex(bucket_order).reset_index()

# ── 6. Customer Insights ──
customer_perf = df.groupby("customer_id").agg(
    total_spent=("revenue", "sum"),
    total_orders=("order_id", "count"),
    avg_order_value=("revenue", "mean"),
    avg_discount=("discount", "mean"),
    total_profit=("profit", "sum"),
    first_purchase=("order_date", "min"),
    last_purchase=("order_date", "max"),
).reset_index()
customer_perf["customer_tenure_days"] = (customer_perf["last_purchase"] - customer_perf["first_purchase"]).dt.days

# RFM-style segmentation
customer_labels = []
for _, c in customer_perf.iterrows():
    orders = c["total_orders"]
    spent = c["total_spent"]
    if orders >= 10 and spent >= customer_perf["total_spent"].quantile(0.75):
        customer_labels.append("High Value")
    elif orders >= 5:
        customer_labels.append("Regular")
    elif orders >= 2:
        customer_labels.append("Occasional")
    else:
        customer_labels.append("One-Time")

customer_perf["segment"] = customer_labels
segment_analysis = customer_perf.groupby("segment").agg(
    customers=("customer_id", "count"),
    total_revenue=("total_spent", "sum"),
    total_profit=("total_profit", "sum"),
    avg_spent=("total_spent", "mean"),
    avg_orders=("total_orders", "mean"),
    avg_aov=("avg_order_value", "mean"),
).reset_index()
segment_order = ["High Value", "Regular", "Occasional", "One-Time"]
segment_analysis = segment_analysis.set_index("segment").reindex(segment_order).reset_index()

# Order frequency distribution
freq_dist = customer_perf["total_orders"].value_counts().sort_index()
freq_dist_df = pd.DataFrame({"orders": freq_dist.index, "customers": freq_dist.values})

# ── Generate JSON data for JavaScript charts ──
chart_data = {
    "monthly_labels": [str(m) for m in monthly["year_month_str"]],
    "monthly_revenue_2023": [float(x) for x in monthly_2023["revenue"]],
    "monthly_revenue_2024": [float(x) for x in monthly_2024["revenue"]],
    "monthly_orders_2023": [int(x) for x in monthly_2023["orders"]],
    "monthly_orders_2024": [int(x) for x in monthly_2024["orders"]],
    "quarterly_labels": [str(q) for q in quarterly["year_quarter_str"]],
    "quarterly_revenue": [float(x) for x in quarterly["revenue"]],
    "quarterly_profit": [float(x) for x in quarterly["profit"]],
    "quarterly_orders": [int(x) for x in quarterly["orders"]],
    "top10_product_labels": top10_revenue["product_id"].tolist(),
    "top10_product_revenue": [float(x) for x in top10_revenue["revenue"]],
    "top10_product_profit": [float(x) for x in top10_revenue["profit"]],
    "top10_product_margin": [round(float(x), 1) for x in top10_revenue["profit_margin_pct"]],
    "top10_stores_revenue_labels": top10_stores_revenue["store_id"].tolist(),
    "top10_stores_revenue": [float(x) for x in top10_stores_revenue["revenue"]],
    "top10_stores_margin": [round(float(x), 1) for x in top10_stores_revenue["profit_margin_pct"]],
    "discount_buckets": discount_analysis["discount_bucket"].tolist(),
    "discount_pct_transactions": [round(float(x), 1) for x in discount_analysis["pct_transactions"]],
    "discount_pct_margin": [round(float(x), 2) for x in discount_analysis["pct_margin"]],
    "discount_avg_qty": [round(float(x), 2) for x in discount_analysis["avg_quantity"]],
    "discount_avg_revenue": [round(float(x), 2) for x in discount_analysis["total_revenue"]],
    "segment_labels": segment_analysis["segment"].tolist(),
    "segment_customers": [int(x) for x in segment_analysis["customers"]],
    "segment_avg_spent": [round(float(x), 2) for x in segment_analysis["avg_spent"]],
    "segment_avg_orders": [round(float(x), 1) for x in segment_analysis["avg_orders"]],
    "segment_avg_aov": [round(float(x), 2) for x in segment_analysis["avg_aov"]],
    "freq_labels": [str(int(x)) for x in freq_dist_df["orders"].tolist()[:15]],
    "freq_counts": [int(x) for x in freq_dist_df["customers"].tolist()[:15]],
}


# ── Additional analyses ──
# Revenue per day of week
df["day_of_week"] = df["order_date"].dt.day_name()
dow_order = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
dow_analysis = df.groupby("day_of_week").agg(
    revenue=("revenue", "sum"),
    orders=("order_id", "count"),
    avg_value=("revenue", "mean"),
).reindex(dow_order).reset_index()

chart_data["dow_labels"] = [d[:3] for d in dow_analysis["day_of_week"].tolist()]
chart_data["dow_revenue"] = [float(x) for x in dow_analysis["revenue"]]

# ── Generate HTML Report ──
print("\nGenerating HTML report...")

html = f"""<!DOCTYPE html>
