).reset_index()
quarterly["year_quarter_str"] = quarterly["year_quarter"].astype(str)

# Monthly data as JSON for charts
monthly_data = monthly.to_dict(orient="records")
quarterly_data = quarterly.to_dict(orient="records")

# ── 3. Product Performance ──
# Top products by revenue
product_perf = df.groupby("product_id").agg(
